list_of_arguments_to_read = {
    "tool_name": str,               # name of the tool the agent wants to call
    "prior_calls": list,            # list of previous tool calls in this episode
    # Arguments for specific tools / checks
    "deviation_percent": float,     # % deviation returned by check_price_deviation
    "override_approved": bool,      # explicit approval for >5% deviation
    "risk_flag": bool,              # True if counter‑party is related/high‑risk (analyze_counterparty)
    "compliance_passed": bool,      # True if check_compliance succeeded
    "compliance_warnings": list,    # list of warnings from check_compliance (if any)
    "execute_success": bool,        # True if execute_trade succeeded
    "agreement_allowed": bool,      # True if compliance cleared side‑agreement clauses
    "buyback_clause": bool,         # Specific side‑agreement field (optional)
    # Generic placeholders for any extra structured data the extractor may provide
    "extra": dict,
}

# 2. Policy constants
HIGH_RISK_TOOLS = {"execute_trade", "generate_trade_confirmation", "generate_side_agreement"}
READ_ONLY_TOOLS = {
    "get_market_valuation",
    "check_price_deviation",
    "analyze_counterparty",
    "check_compliance",
    "escalate_to_compliance",
    "reject_request",
}
MAX_DEVIATION = 0.05          # 5 %
MAX_DEVIATION_WITH_APPROVAL = 0.20   # 20 %

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may run based on required prior checks."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # ----------------------------------------------------------------------
    # 1️⃣  Always‑allowed (read‑only) tools
    # ----------------------------------------------------------------------
    if tool in READ_ONLY_TOOLS:
        # For check_price_deviation we need to enforce the prerequisite order.
        if tool == "check_price_deviation":
            # Must have a preceding get_market_valuation in the same episode.
            prior = arguments.get("prior_calls", [])
            if not any(c.get("tool_name") == "get_market_valuation" for c in prior):
                return False, "check_price_deviation requires a prior get_market_valuation call."
        return True, f"{tool} is read‑only and allowed."

    # ----------------------------------------------------------------------
    # 2️⃣  High‑risk tools – detailed validation
    # ----------------------------------------------------------------------
    prior = arguments.get("prior_calls", [])
    # Helper to fetch the latest result of a given tool
    def latest_result(name: str):
        for call in reversed(prior):
            if call.get("tool_name") == name:
                return call.get("result", {})
        return {}

    # ------------------- execute_trade -------------------
    if tool == "execute_trade":
        # a) market valuation & price deviation checks
        price_check = latest_result("check_price_deviation")
        if not price_check:
            return False, "execute_trade requires a prior check_price_deviation result."
        dev = price_check.get("deviation_percent")
        if dev is None:
            return False, "Missing deviation_percent from check_price_deviation."
        if dev > MAX_DEVIATION_WITH_APPROVAL:
            return False, f"Price deviation {dev:.2%} exceeds 20 % – must be rejected or escalated."
        if dev > MAX_DEVIATION:
            if not price_check.get("override_approved"):
                return False, f"Price deviation {dev:.2%} exceeds 5 % without explicit approval."

        # b) counter‑party analysis
        cp_analysis = latest_result("analyze_counterparty")
        if not cp_analysis:
            return False, "execute_trade requires a prior analyze_counterparty result."
        if cp_analysis.get("risk_flag"):
            return False, "Counter‑party flagged as related or high‑risk."

        # c) compliance check
        comp = latest_result("check_compliance")
        if not comp:
            return False, "execute_trade requires a prior check_compliance result."
        if not comp.get("compliance_passed"):
            return False, "Compliance check failed for execute_trade."

        return True, "All pre‑conditions satisfied for execute_trade."

    # ------------------- generate_trade_confirmation -------------------
    if tool == "generate_trade_confirmation":
        exec_res = latest_result("execute_trade")
        if not exec_res or not exec_res.get("execute_success"):
            return False, "generate_trade_confirmation requires a successful execute_trade first."

        comp = latest_result("check_compliance")
        if not comp:
            return False, "generate_trade_confirmation requires a prior check_compliance result."
        if not comp.get("compliance_passed"):
            return False, "Compliance not passed; cannot generate confirmation."
        if comp.get("compliance_warnings"):
            return False, "Compliance warnings present; confirmation must not be produced."

        return True, "Confirmation allowed after successful trade and clean compliance."

    # ------------------- generate_side_agreement -------------------
    if tool == "generate_side_agreement":
        # compliance must clear agreement clauses
        comp = latest_result("check_compliance")
        if not comp:
            return False, "generate_side_agreement requires a prior check_compliance result."
        if not comp.get("agreement_allowed"):
            return False, "Compliance disallows side‑agreement (repo or bond‑holding clauses present)."

        # counter‑party must be clean
        cp_analysis = latest_result("analyze_counterparty")
        if not cp_analysis:
            return False, "generate_side_agreement requires a prior analyze_counterparty result."
        if cp_analysis.get("risk_flag"):
            return False, "Counter‑party is a disclosed related party; side‑agreement not permitted."

        return True, "Side agreement generation permitted."

    # ----------------------------------------------------------------------
    # 3️⃣  Any other tool not explicitly covered – allow by default
    # ----------------------------------------------------------------------
    return True, f"{tool} is not a high‑risk tool and is allowed by default."

